Fíjate en el orden: el tam[u] += va después del dfs(v, u), porque
necesita que el hijo ya haya terminado. Cambia el “absorbe” y tienes sumas,
máximos, alturas, conteos de hojas… Este patrón es la semilla de la DP en
árboles (DP en árboles (rerooting) cuando llegue el momento de la
versión avanzada).
La misma acumulación sin recursión
Podemos guardar un orden donde cada padre aparezca antes que sus hijos; al recorrerlo al revés, cada hijo ya tiene su tamaño. Este bloque reemplaza las llamadas a enraizar y dfs y usa las mismas variables:

// usa: ady, padre, prof, tam
int cantidad = ady.size(); // árbol no vacío, nodos 0..cantidad-1
padre.assign(cantidad, -1);
prof.assign(cantidad, 0);
tam.assign(cantidad, 1);
vector&lt;int&gt; orden = {0};
for (int i = 0; i &lt; (int)orden.size(); i++) {
    int u = orden[i];
    for (int v : ady[u]) if (v != padre[u]) {
        padre[v] = u;
        prof[v] = prof[u] + 1;
        orden.push_back(v);
    }
}
for (int i = cantidad - 1; i &gt; 0; i--) {
    int u = orden[i];
    tam[padre[u]] += tam[u];
}
Cuesta O(n) tiempo y memoria, también en un árbol con forma de camino. El bloque supone que la entrada es un árbol; no sustituye el marcado de visitados en un grafo general.
El diámetro: el camino más largo
El truco de los dos recorridos: parte de cualquier nodo, anda al más
lejano a; desde a, anda al más lejano b. La distancia a→b es el
diámetro. Con el BFS del módulo 15 son cuatro
líneas:

// supone: int n; vector&lt;vector&lt;int&gt;&gt; ady;  // nodos 0..n-1
// devuelve {nodo más lejano desde s, su distancia}
pair&lt;int,int&gt; mas_lejano(int s) {
    vector&lt;int&gt; d(n, -1); queue&lt;int&gt; q;
    d[s] = 0; q.push(s);
    int lejano = s;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (d[u] &gt; d[lejano]) lejano = u;
        for (int v : ady[u]) if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }
    }
    return {lejano, d[lejano]};
}
